	/* @Override */
	public bool isEnabledForContext(DomainFileContext context) {
		if (isFileSystemBusy()) {
			return false; // don't block; we should get called again later
		}

		List<DomainFile> providedList = context.getSelectedFiles();
		foreach (DomainFile domainFile in providedList) {
			if (domainFile.canCheckout()) {
				return true; // At least one version controlled, non-checked out file selected.
			}
		}
		return false;
	}

