			if (failedFiles.size() == 1) {
				DomainFile df = failedFiles.get(0);
				string s = "Exclusive checkout failed for: " + df.getName() +
					"\nOne or more users have file checked out!";
				Msg.showError(this, tool.getToolFrame(), "Checkout Failed", s);
				return;
